package run.ikaros.finance; import java.time.Instant; import java.util.UUID; import org.springframework.stereotype.Service; import reactor.core.publisher.Mono; import run.ikaros.common.NotFoundException; @Service public class LedgerLifecycleService{private final LedgerRepository ledgers;public LedgerLifecycleService(LedgerRepository l){ledgers=l;}public Mono<LedgerView> setArchived(UUID a,UUID id,boolean archived){return ledgers.findById(id).filter(l->l.ownerId().equals(a)).switchIfEmpty(Mono.error(new NotFoundException("Ledger 不存在或无权访问"))).flatMap(l->ledgers.save(new LedgerEntity(l.id(),l.ownerId(),l.name(),l.baseCurrency(),archived,l.createdAt(),Instant.now(),l.version()))).map(this::view);}private LedgerView view(LedgerEntity l){return new LedgerView(l.id(),l.ownerId(),l.name(),l.baseCurrency(),l.archived(),l.createdAt());}}
